begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001401','ai13@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000001401','AI test','00000000-0000-4000-8000-000000001401');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401');
insert into public.entitlement_overrides(family_id,plan,reason,ends_at) values('10000000-0000-4000-8000-000000001401','plus','test',now()+interval '1 day');
update public.plans set prova_ai_generate_monthly=2 where code='plus';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000001401","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000001401","role":"parent"}}',true);
select throws_ok($$select public.reserve_prova_generation('40000000-0000-4000-8000-000000001401','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','hash',2)$$,'42501',null,'client cannot reserve quota directly');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.reserve_prova_generation('40000000-0000-4000-8000-000000001401','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','hash',2)->>'ok','true','server reserves requested quota');
select is(public.reserve_prova_generation('40000000-0000-4000-8000-000000001402','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','hash2',1)->>'error','ai_quota_exceeded','concurrent request cannot consume reserved quota');
select is(public.reserve_prova_generation('40000000-0000-4000-8000-000000001401','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','hash',2)->>'error','generation_in_progress','same request does not start second generation');
select is(public.reserve_prova_generation('40000000-0000-4000-8000-000000001401','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','changed',2)->>'error','request_conflict','same id cannot change prompt');
select is(public.complete_prova_generation('40000000-0000-4000-8000-000000001401','[{"grade":5,"subject":"Fen","topic":"Isı","kind":"open_ended","difficulty":"orta","stem":"Isı nedir?","expected_answer":"Enerji aktarımı","solution":"Açıklama","source_urls":[],"provenance":{}}]','test-model','test',10,20)->>'ok','true','result saved atomically');
select is(public.complete_prova_generation('40000000-0000-4000-8000-000000001401','[]','test-model','test',10,20)->>'ok','true','lost response retry returns saved result');
select is((select count(*)::int from public.question_bank where family_id='10000000-0000-4000-8000-000000001401'),1,'retry creates no duplicate questions');
select is((select sum(items)::int from public.prova_ai_usage where family_id='10000000-0000-4000-8000-000000001401'),1,'retry charges quota only once');
select ok(public.reserve_prova_generation('40000000-0000-4000-8000-000000001401','10000000-0000-4000-8000-000000001401','00000000-0000-4000-8000-000000001401','hash',2) ? 'cached','finished request returns cached response before quota check');
reset role;
select * from finish();
rollback;
